class UnionFind:
    def __init__(self):
        self.father = {}
        # 统一集合中，当前点到根节点奇偶性
        self.d = {}    

    def find(self, x):        
        self.add(x)
        # 一次性平铺          
        if self.father[x] != x:  
            rt = self.find(self.father[x])                     
            self.d[x] = (self.d[x]+self.d[self.father[x]])&1
            self.father[x] = rt

        return self.father[x]                

    def merge(self, x, y, w):
        root_x, root_y = self.find(x), self.find(y)
        if root_x!=root_y:
            self.father[root_x] = root_y 
            self.d[root_x] = (self.d[x]+w+self.d[y])&1       

    def is_connected(self, x, y):
        return self.find(x)==self.find(y)

    def add(self, x):
        if x not in self.father:
            self.father[x] = x   
            self.d[x] = 0     
class Solution:
    def numberOfEdgesAdded(self, n: int, edges: List[List[int]]) -> int:
        uf = UnionFind()
        res = 0
        for x,y,w in edges:
            if not uf.is_connected(x,y):
                uf.merge(x,y,w)
                res += 1
            elif not (uf.d[x]+uf.d[y]+w)&1:
                res += 1

        return res

