class Solution:
    def kthRemainingInteger(self, nums: list[int], queries: list[list[int]]) -> list[int]:
        # 前缀和预处理求区间偶数数目
        pre = [0]
        for num in nums:
            pre.append(pre[-1])
            if not num&1:
                pre[-1] += 1
        mx = int(1e10)
        res = 0

        def check(l,r,k,num):
            # 特判剪枝
            if num * 2 < nums[l]:
                return num >= k
            # 特判剪枝
            if num * 2 > nums[r]:
                t = pre[r+1] - pre[l]
                return num - t >= k

            # 二分计算 num * 2 在 nums[l:r+1] 中的位置
            start = l
            end = r
            while start <= end:
                middle = (start + end) // 2
                if nums[middle] <= num*2:
                    start = middle + 1
                else:
                    end = middle - 1

            # 获取 < num * 2 有多少个偶数被删除了
            t = pre[start] - pre[l]
            return num - t >= k

        res = []
        for l,r,k in queries:
            # 二分答案，这里把结果除以2，方便二分
            start = 1
            end = mx
            while start <= end:
                middle = (start + end) // 2
                if not check(l,r,k,middle):
                    start = middle + 1
                else:
                    end = middle - 1
            # 最后要乘以 2
            res.append(start*2)
        return res

