class Solution:
    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        # 排序arr2，方便二分查找
        arr2.sort()
        # 存储最终的合法数
        ans = 0
        for num1 in arr1:
            # 公式里面的a - d
            low = num1 - d
            # 公式里面的a + d
            high = num1 + d
            # 二分查找，如果没有找到这个b，那么a就合法了
            if not self.binarySearch(arr2, low, high):
                ans += 1
        return ans

    def binarySearch(self, arr, low, high):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = left + (right - left) // 2
            # 满足公式，找到b了
            if arr[mid] >= low and arr[mid] <= high:
                return True
            elif arr[mid] < low:
                # 似乎要往右边动一动，才能找到这个b
                left = mid + 1
            else:
                # 似乎要往左边动一动，才能找到这个b
                right = mid - 1
        return False

