class Solution:
    def maxConsistentColumns(self, grid: List[List[int]], limit: int) -> int:
        shuffle(grid)
        candidates = []
        N = len(grid)
        M = len(grid[0])
        for j in range(M):
            insert_pos = len(candidates)
            insert_value = candidates[-1][1] if candidates else 1
            for k in range(len(candidates) - 1, -1, -1):
                x, v = candidates[k]
                for i in range(N):
                    if abs(grid[i][x] - grid[i][j]) > limit:
                        break
                else:
                    break
            else:
