class Solution:
    def maxSubgraphScore(self, n: int, edges: List[List[int]], good: List[int]) -> List[int]:
        # 建图
        road = defaultdict(list)
        for x,y in edges:
            road[x].append(y)
            road[y].append(x)

        n = len(good)
        # 每个节点所在子树的 最大子图 得分
        dp = [0] * n
        # 树形dp
        def dfs(node,last):
            # 自身权值
            if good[node]:
                dp[node] += 1
            else:
                dp[node] -= 1      

            for nxt in road[node]:
                if nxt == last:
                    continue

                lt = dfs(nxt,node)
                # 贪心，只取正
                if lt > 0:
                    dp[node] += lt

            return dp[node]

        dfs(0,-1)
        res = [0] * n
        # 换根dp
        def chroot(node,last):
            res[node] = dp[node]

            for nxt in road[node]:
                if nxt == last:
                    continue

                # 换根，dp[node] 先去掉 nxt 这个分支
                if dp[nxt] > 0:
                    tmp = dp[node]-dp[nxt]
                else:
                    tmp = dp[node]

                # nxt 作为根。从新绑定 node 这个分支
                if tmp > 0:
                    dp[nxt] += tmp

                chroot(nxt,node)
                # 回溯
                if tmp > 0:
                    dp[nxt] -= tmp

        chroot(0,-1)
        return res

