from functools import cache
from math import inf

class Solution:
    def minCost(self, source: str, target: str, rules: list[list[str]], costs: list[int]) -> int:
        n = len(source)

        def match(pattern: str, text: str) -> bool:
            """判断 pattern 是否匹配 text（支持 '*' 通配）"""
            if len(pattern) != len(text):
                return False
            for p, t in zip(pattern, text):
                if p != '*' and p != t:
                    return False
            return True

        # 建图：jumps[i] 存储从位置 i 出发的所有合法跳跃 (步长, 成本)
        jumps = defaultdict(list)
        for cost_base, (pat, rep) in zip(costs, rules):
            length = len(pat)
            jump_cost = cost_base + pat.count('*')
            for i in range(n - length + 1):
                # 必须同时满足：pattern 能踩中 source，且 replacement 能对齐 target
                if match(pat, source[i:i+length]) and match(rep, target[i:i+length]):
                    jumps[i].append((length, jump_cost))

        @cache
        def dp(i: int) -> int:
            """跳跃游戏核心：从位置 i 跳到末尾的最小成本"""
            if i == n:
                return 0

            # 选项1：当前位置字符相同，可“免费单步跳” i -> i+1
            res = dp(i + 1) if source[i] == target[i] else inf

            # 选项2：尝试所有从 i 出发的规则跳跃
            for step, c in jumps[i]:
                res = min(res, dp(i + step) + c)

            return res

        ans = dp(0)
        dp.cache_clear()
        return -1 if ans == inf else ans

