class UnionFind:
    def __init__(self):
        self.father = {}

    def find(self, x):
        self.add(x)               
        # 一次性平铺          
        if self.father[x] != x:
            self.father[x] = self.find(self.father[x])

        return self.father[x]               

    def merge(self, x, y):
        root_x, root_y = self.find(x), self.find(y)
        if root_x!=root_y:       
            self.father[root_x] = root_y

    def is_connected(self, x, y):
        return self.find(x)==self.find(y)

    def add(self, x):
        if x not in self.father:
            self.father[x] = x

class Solution:
    def maxAlternatingSum(self, nums: List[int], swaps: List[List[int]]) -> int:
        '''
        偶 - 奇 最大
        并查集
        '''

        # 同组元素可以随意交换，即可以任意顺序
        uf = UnionFind()
        for x,y in swaps:
            uf.merge(x,y)

        # 分组
        n = len(nums)
        # 记录每个组对应的数字
        gp = defaultdict(list)
        # 记录每个组奇数下标数目
        cnt = Counter()
        for i,num in enumerate(nums):
            rt = uf.find(i)
            gp[rt].append(num)
            cnt[rt] += i&1

        # 排序 贪心
        res = 0
        for rt,arr in gp.items():
            # 当前组奇数数目
            o = cnt[rt]
            arr.sort()
            for num in arr:
                # 越小的值放到奇数位
                if o:
                    res -= num
                    o -= 1
                else:
                    res += num

        return res

