class Solution:
    def getf(self, f, x):
        if f[x] == x:
            return x
        newf = self.getf(f, f[x])
        f[x] = newf
        return newf

    def add(self, f, x, y):
        fx = self.getf(f, x)
        fy = self.getf(f, y)
        f[fx] = fy

    def minSwapsCouples(self, row: List[int]) -> int:
        n = len(row)
        tot = n // 2
        f = [i for i in range(tot)]

        for i in range(0, n, 2):
            l = row[i] // 2
            r = row[i + 1] // 2
            self.add(f, l, r)

        m = {}
        for i in range(tot):
            fx = self.getf(f, i)
            if fx in m:
                m[fx] += 1
            else:
                m[fx] = 1

        ret = 0
        for f, sz in m.items():
            ret += sz - 1

        return ret

