class Solution:
    def evenSumSubgraphs(self, nums: list[int], edges: list[list[int]]) -> int:
        n = len(nums)
        tgt = 1 << n
        dp = [False] * tgt        
        road = defaultdict(list)
        for x,y in edges:  
            road[x].append(y)       
            road[y].append(x)
        # 单点当然连通
        for i in range(n):
            dp[1 << i] = True

        for s in range(tgt):
            # 非连通
            if not dp[s]:
                continue

            for i in range(n):
                # 不在s中
                if not (1 << i)&s:
                    continue
                # 边
                for j in road[i]:
                    dp[s|(1<<j)] = True

        res = 0         
        for s in range(tgt):
