class Solution:
    def maxXorSubsequences(self, nums: List[int]) -> int:
        '''
        线性基 模板题
        '''
        level = 31
        dt = {}
        for num in nums:
            for i in range(level,-1,-1):
                s = 1 << i
                if s&num:
                    if s not in dt:
                        dt[s] = num
                        break
                    else:
