class Solution:
    def smallestNumber(self, pattern: str) -> str:
        n = len(pattern)
        ans = ["" for _ in range(n + 1)]
        inDegree = [0 for _ in range(n + 1)]
        g = defaultdict(list)
        for idx, val in enumerate(pattern):
            if val == "I":
                g[idx].append(idx + 1)
                inDegree[idx + 1] += 1
            elif val == "D":
                g[idx + 1].append(idx)
                inDegree[idx] += 1
        queue = []
        for i in range(n + 1):
            if inDegree[i] == 0:
                heapq.heappush(queue, i)
        count = 1
        while queue:
            node = heapq.heappop(queue)
            ans[node] = str(count)
            count += 1
            edges = g[node]
            for edge in edges:
                inDegree[edge] -= 1
                if inDegree[edge] == 0:
                    heapq.heappush(queue, edge)
        return "".join(ans)

