class Solution:

    def spiralMatrix(self, m: int, n: int, head: Optional[ListNode]) -> List[List[int]]:
        l, r, t, b = 0, n - 1, 0, m - 1
        mat = [[-1 for _ in range(n)] for _ in range(m)]
        while head:
            # from left to right
            for i in range(l, r + 1):
                if head:
