                    mat[i][r] = head.val
                    head = head.next
            r -= 1
            # from right to left
            for i in range(r, l - 1, -1):
                if head:
                    mat[b][i] = head.val
                    head = head.next
            b -= 1
            # from buttom to top
            for i in range(b, t - 1, -1):
                if head:
                    mat[i][l] = head.val
                    head = head.next
            l += 1


