class Solution:
    def sumOfPrimesInRange(self, n: int) -> int:
        def reverse(n: int) -> bool:
            r = 0
            while n:
                r = r * 10 + n % 10
                n //= 10
            return r

        def isPrime(num: int) -> bool:
            if num == 1:
                return False
            if not num % 2:
                return num == 2
            i = 3
            while i * i <= num:
                if not num % i:
                    return False
                i += 2
            return True

        sum = 0
        r = reverse(n)
        start = min(n, r)
        end = max(n, r)
        for i in range(start, end + 1):
            if isPrime(i):
                sum += i
        return sum

