        def isPalindromic(n: int, radix: int) -> bool:
            nums = []
            while n > 0:
                nums.append(n % radix)
                n //= radix
            left, right = 0, len(nums) - 1
            while left < right:
                if nums[left] != nums[right]:
                    return False
                left += 1
                right -= 1
            return True

        for radix in range(2, n - 1):
            if not isPalindromic(n, radix):
                return False
        return True

