class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def _list_build(vals):
    head = cur = ListNode()
    for v in vals:
        cur.next = ListNode(v)
        cur = cur.next
    return head.next

def _list_show(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def _list_array_build(arr):
    return [_list_build(x) for x in arr]

def _list_array_show(arr):
    return [_list_show(x) for x in arr]

class Solution:
    def pairSum(self, head: Optional[ListNode]) -> int:
        slow, fast = head, head.next
        while fast.next:
            slow = slow.next
            fast = fast.next.next

        # 反转链表
        last = slow.next
        while last.next:
            cur = last.next
            last.next = cur.next
            cur.next = slow.next
            slow.next = cur

        ans = 0
        x, y = head, slow.next
        while y:
            ans = max(ans, x.val + y.val)
            x, y = x.next, y.next
        return ans

