class Solution:
    def minCost(self, s: str, encCost: int, flatCost: int) -> int:
        pre = [0]
        for w in s:
            pre.append(pre[-1])
            if w == '1':
                pre[-1] += 1

        def getCost(l,r):
            X = pre[r+1] - pre[l]
            if not X:
                return flatCost               
            return (r-l+1)*X*encCost


        @cache
        def dfs(l,r):
            # 奇数长度不能拆分
            if (r - l + 1)&1:
                return getCost(l,r)

            # 偶数长度
            # 不拆
            A = getCost(l,r)
            # 拆
            m = (l+r)//2
            B = dfs(l,m)+dfs(m+1,r)
            return min(A,B)

        res = dfs(0,len(s)-1)
        dfs.cache_clear()

        return res

