class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        old = [0]*128
        new = [0]*128
        for i, c in enumerate(s):
            new[ord(c)] |= 1 << i
        for i in range(128):
