class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        '''
        最长公共前缀，字典树
        次长公共前缀
        '''
        n = len(words)
        tree = {}

        # 不移除任何
        for i,word in enumerate(words):
            pos = tree
            for j,w in enumerate(word):
                if w not in pos:
                    pos[w] = {}
                    # 第i个word，第j个字母
                    pos[w]['idx'] = i
                    pos[w]['end'] = j+1
                    # 计数
                    pos[w]['cnt'] = 0
                pos = pos[w]
                pos['cnt'] += 1

        tree['cnt'] = n
        tree['end'] = 0
        tree['idx'] = 0

        # 获取最长lcp
        def dfs(pos):
            if pos['cnt'] < k:
                return (0,k+1,0)
            # 长度，数目，下标
            res = (pos['end'],pos['cnt'],pos['idx'])
            for w in pos.keys():
                if len(w) == 1:
                    lres = dfs(pos[w])
                    if lres > res:
                        res = lres
            return res

        # 不移除任何word的lcp
        tmp = dfs(tree)
        # 剪枝，移除任何word后，lcp都能凑够k个
        if tmp[1] > k:
            return [tmp[0]] * n

        # lcp对应字符串
        t1 = tmp[0]
        pre = words[tmp[2]][:t1]

        # 去掉pre，再求一次lcp。即次长lcp
        pos = tree
        tree['cnt'] -= 1
        for w in pre:
            pos = pos[w]
            pos['cnt'] -= 1

        t2 = dfs(tree)[0]

        res = []
