    def goodSubsetofBinaryMatrix(self, grid: List[List[int]]) -> List[int]:
        ans = []
        mp = {}
        m = len(grid)
        n = len(grid[0])

        for j in range(m):
            st = 0
            for i in range(n):
                st |= (grid[j][i] << i)
